        static Dictionary<string, Dictionary<string, string>> _extra;

        // 字段数不对的行不抛异常（那会让程序启动即崩），记下来由 --i18ncheck 点名
        public static readonly List<string> BadRows = new List<string>();

        static Dictionary<string, Dictionary<string, string>> Extra()
        {
            if (_extra != null) return _extra;

            Dictionary<string, Dictionary<string, string>> m =
                new Dictionary<string, Dictionary<string, string>>(StringComparer.Ordinal);

            foreach (string row in Rows)
            {
                int bar = row.IndexOf('|');
                if (bar <= 0) { BadRows.Add("?"); continue; }

                string code = row.Substring(0, bar);
                string[] f = row.Substring(bar + 1).Split('|');
                if (f.Length != Core.Length)
                {
                    BadRows.Add(code + " " + f.Length + "/" + Core.Length);
                    continue;
                }

                string[] kv = new string[Core.Length * 2];
                for (int i = 0; i < Core.Length; i++)
                {
                    kv[i * 2] = Core[i];
                    kv[i * 2 + 1] = f[i];
                }
                m[code] = D(kv);
            }

            _extra = m;
            return m;
        }

        // 没有这张表（或代码写错）时返回 null，调用方回落英语
        static Dictionary<string, string> ExtraTable(string code)
        {
            Dictionary<string, string> t;
            return Extra().TryGetValue(code, out t) ? t : null;
        }
    }
